// ---------- кто где живёт: от этого зависит облик поселения в 3D (scripts/lore/cities-auto.mjs → city3d.ts) ----------
// deep — подгорный чертог дварфов (город в пещере), dwarf — каменные твердыни и рудничные посёлки (только дварфы),
// gnome — гномьи долины и торговые городки (только гномы), human — замки и городки имперской знати Поверхности
export function fvRace(name, type, land) {
  if (name === 'Норг-Бад') return 'deep'
  if (name === 'Барак-Ази') return 'gnome'
  if (land === 'Килский хребет' || land === 'Дум-Аский хребет') return /Гунд|гунд|Дум|дум|Бад|бад/.test(name) && type !== 'tower' && name !== 'Азг-Кар' ? 'deep' : 'dwarf'
  if (land === 'Грунский хребет') return type === 'castle' ? 'dwarf' : 'gnome'
  return ['castle', 'town', 'city'].includes(type) ? 'human' : 'gnome'
}
